import{_ as n,C as e,o as s,c as d,E as a,a2 as o}from"./chunks/framework.BdWD-ld-.js";const _=JSON.parse('{"title":"对话停止了，任务该凭什么验收","description":"","frontmatter":{"title":"对话停止了，任务该凭什么验收","article_type":"engineering-insight","edition":"research-center","research_question":"对话处理结果与停止原因，为什么不能代替任务的领域验收？","summary":"两个不同停止分支返回同一个处理结果，说明编排返回值不能直接充当任务成绩。结合经典实现的内部隔离探针与独立失败分类研究，本文区分停止、验证行为和业务验收，并保留增加验证者的效果边界。","sources":"https://raw.githubusercontent.com/ag2ai/ag2/v0.9.10/autogen/agentchat/groupchat.py; https://arxiv.org/html/2503.13657v3","date":"2026-11-23","column":"open-source-engineering","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261123-004","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-23-sig-20261123-004-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-11-23-sig-20261123-004.md","filePath":"zh/engineering/2026-11-23-sig-20261123-004.md","lastUpdated":null}'),h={name:"zh/engineering/2026-11-23-sig-20261123-004.md"};function l(c,t,p,g,u,b){const r=e("ArticleCover"),i=e("ArticleTableScroll");return s(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-11-23-sig-20261123-004-cover.png",kicker:"研究成果",title:"对话停止了，任务该凭什么验收",summary:"两个不同停止分支返回同一个处理结果，说明编排返回值不能直接充当任务成绩。结合经典实现的内部隔离探针与独立失败分类研究，本文区分停止、验证行为和业务验收，并保留增加验证者的效果边界。",version:"2026-11-23",languageHref:"/en/engineering/2026-11-23-sig-20261123-004",languageLabel:"English"}),a(i,{language:"zh"}),t[0]||(t[0]=o('<h1 id="对话停止了-任务该凭什么验收" tabindex="-1">对话停止了，任务该凭什么验收 <a class="header-anchor" href="#对话停止了-任务该凭什么验收" aria-label="Permalink to &quot;对话停止了，任务该凭什么验收&quot;">​</a></h1><p>一条消息写着“尚未完成”，另一条写着“完成”。在同日分析阶段的内部隔离探针中，它们分别触发轮数上限和终止消息条件，却返回同一个处理结果。如果上层把这个返回值写成“任务成功”，预算耗尽就可能被误当成业务验收。多智能体编排工程师需要保留停止原因，并另行索取产物及验收依据。</p><h2 id="同一个返回值-两种停止原因" tabindex="-1">同一个返回值，两种停止原因 <a class="header-anchor" href="#同一个返回值-两种停止原因" aria-label="Permalink to &quot;同一个返回值，两种停止原因&quot;">​</a></h2><p>AG2（多智能体应用框架）的经典群聊指南描述管理者如何选择发言者、广播上下文、限制轮数，以及按消息标记结束对话。这些是组织对话的机制；一个结束标记不自动说明交付物满足了要求。<a href="https://docs.ag2.ai/latest/docs/user-guide/advanced-concepts/groupchat/groupchat/" target="_blank" rel="noreferrer">经典群聊指南</a></p><p>本次分析固定了经典版本 0.9.10 的源码，提交为 <code>ac380f5c7962ad875f77c4f8310e3c1167bceeb7</code>（固定源码提交标识）。内部实验提取管理者的 <code>run_chat</code>（运行群聊方法）函数体，保留源码逻辑，用惰性的管理者、群组、消息和事件替身隔离依赖。对照使用同样的一轮上限，只改变消息和终止谓词。</p><table tabindex="0"><thead><tr><th>输入与条件</th><th>实际停止事件</th><th>返回结果</th><th>是否检查业务成功</th></tr></thead><tbody><tr><td>“尚未完成”，终止谓词为假</td><td>达到一轮上限</td><td>相同处理元组</td><td>否</td></tr><tr><td>“完成”，终止谓词为真</td><td>管理者终止消息条件满足</td><td>相同处理元组</td><td>否</td></tr></tbody></table><p>两个分支实际都返回下列值。它是消息处理结果，不是独立计算的业务成绩：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>这不是“框架把失败算成成功”的实验。错误会发生在消费端把处理语义扩大成验收语义时。静态源码还区分没有可选发言者、没有生成回复等停止路径；这次探针只执行了表中两个分支。<a href="https://raw.githubusercontent.com/ag2ai/ag2/v0.9.10/autogen/agentchat/groupchat.py" target="_blank" rel="noreferrer">经典源码</a>；<a href="/joinwell52/assets/evidence/2026-11-23-sig-20261123-004/experiment-evidence.json">内部实验输入、输出与边界</a></p><h2 id="验证标签与任务结果各自说明什么" tabindex="-1">验证标签与任务结果各自说明什么 <a class="header-anchor" href="#验证标签与任务结果各自说明什么" aria-label="Permalink to &quot;验证标签与任务结果各自说明什么&quot;">​</a></h2><p>MAST（多智能体系统失败分类研究）来自另一研究团队。第三版论文报告分析七种框架的 1642 条轨迹，区分过早终止、缺失或不完整验证、错误验证等模式。这些分类帮助解释发生了什么，并不与最终任务失败一一对应；论文也指出，验证相关标签会出现在成功运行中。<a href="https://arxiv.org/html/2503.13657v3" target="_blank" rel="noreferrer">论文第三版，第 3—4 节及成功轨迹分析附录</a></p><p>附录案例给出了比“多检查一次”更具体的问题：有案例遗漏了鱼价假设的核查；有案例算对了支出，却回答了剩余金额；另有编辑者声称已经修改，后续测试却显示修改不存在。它们分别涉及前提、交付目标和实际产物，不是同一种终止条件失灵。</p><p>因此需要分开记录三件事：对话为什么结束，谁做过什么验证，交付物最终满足了哪些要求。验证者给出了肯定答案，是一项过程事实；它看到了错误产物或检查了错误问题，仍可能给出错误验收。反过来，一次成功结果也不能证明所有验证步骤都完整。</p><h2 id="增加验证者仍然需要条件" tabindex="-1">增加验证者仍然需要条件 <a class="header-anchor" href="#增加验证者仍然需要条件" aria-label="Permalink to &quot;增加验证者仍然需要条件&quot;">​</a></h2><p>论文的数学对话实验为“增加验证者”提供了重要反例。作者在抽取的 200 道增强数学题（题集名称为 GSM-Plus）上进行了六次重复：采用特定编排结构后，第四代模型（论文标记为 GPT-4）的正确率由 84.75 变为 85.50，威尔科克森检验的概率值为 0.4；提示改写得到 89.75。另一全模态版本（论文标记为 GPT-4o）的结构调整由 84.25 变为 88.83，报告的概率值为 0.03。<a href="https://arxiv.org/html/2503.13657v3" target="_blank" rel="noreferrer">干预实验附录、表 5 和完整提示附录</a></p><p>前一组小幅提高没有达到该实验报告的显著差异，不能据此宣布结构调整普遍有效；后一组也不支持把结论推广到所有任务、模型和验证者。附录另有按失败标签观察到的改善趋势，标签分布与最终正确率仍是不同指标。</p><p>这并不否定专职验证者的价值。它意味着要把责任分配和性能收益分开：规定只有验证者可以发出终止标记，可以改变谁有权结束对话；是否提高任务质量，还要检查它看到了什么、怎样判断以及结果如何测量。</p><h2 id="给验收保留独立的证据交接" tabindex="-1">给验收保留独立的证据交接 <a class="header-anchor" href="#给验收保留独立的证据交接" aria-label="Permalink to &quot;给验收保留独立的证据交接&quot;">​</a></h2><p>下面以“修改一个计算函数”为明确标注的设计示例，说明一种建议交接。它不是已测量的新功能，也不是该框架现有接口的说明。</p><table tabindex="0"><thead><tr><th>阶段</th><th>责任主体与输入</th><th>应交付的依据</th><th>无法验收的情况</th></tr></thead><tbody><tr><td>修改要求进入执行</td><td>任务负责人提供预期行为与可检查条件</td><td>要求对应的产物版本</td><td>要求含糊或目标被替换</td></tr><tr><td>对话退出</td><td>编排管理者处理消息与预算</td><td>停止原因、最终消息、产物定位</td><td>只有布尔处理结果</td></tr><tr><td>产物进入检查</td><td>业务验证者读取该版本及要求</td><td>实际执行的测试、输出及未检查项</td><td>只读到编辑者的完成宣称</td></tr><tr><td>检查进入验收</td><td>责任人依据检查结果作决定</td><td>对哪些要求通过、拒绝或暂缓的明确判断</td><td>测试产物与待交付版本不能对应</td></tr></tbody></table><p>如果轮数耗尽而产物未准备好，应保留停止事实并暂缓业务验收；如果产物已经满足要求，即使对话由预算结束，也可以由独立的领域检查作出通过决定。这里的“独立”指验收责任与编排返回值分离，不把本次内部实验包装成第三方验证。</p><p>可执行的第一项检查是找到把群聊返回值映射为任务状态的那段代码，查看它是否还索取停止原因、产物版本和业务检查结果。需要补什么测试，由具体交付要求决定。一个消息关键词既不能代替测试输出，也不能替责任人决定缺项是否可接受。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ul><li><a href="https://docs.ag2.ai/latest/docs/user-guide/advanced-concepts/groupchat/groupchat/" target="_blank" rel="noreferrer">经典群聊指南</a>与<a href="https://raw.githubusercontent.com/ag2ai/ag2/v0.9.10/autogen/agentchat/groupchat.py" target="_blank" rel="noreferrer">固定经典源码</a>：维护者提供的接口与实现依据，属于同一个来源主体。源码提取探针是内部实验，不是完整框架运行；没有调用模型、运行异步路径、工具、发言者选择或防护机制。</li><li><a href="https://arxiv.org/html/2503.13657v3" target="_blank" rel="noreferrer">失败分类研究第三版</a>：梅尔特·杰姆里、梅利莎·潘、舒仪·杨、拉克希亚·阿格拉瓦尔及加州大学伯克利分校合作者的论文，第三版日期为 2025-10-26。这是既有研究，不是今天新发生的故障；轨迹数量、案例和干预结果均按作者报告处理，没有在本次复现。</li><li><a href="https://raw.githubusercontent.com/ag2ai/ag2/db7194e8e26705381d9d23c402ba2bc5cadc67fa/website/docs/user-guide/network/migration_from_group_chat.mdx" target="_blank" rel="noreferrer">当前迁移指南</a>：本次已读固定版本将经典群聊映射到新的工作流适配器和转换图，也映射轮数配置。新架构正确性未在本次测试。</li><li><a href="https://huggingface.co/datasets/mcemri/MAST-Data" target="_blank" rel="noreferrer">研究数据卡</a>：与论文属于同一研究主体。当前数据卡列出 19 条人工研究记录，论文写 21 条人工轨迹；这个差异尚未解释，也没有逐文件独立清点。</li></ul><h2 id="保留版本边界与未解问题" tabindex="-1">保留版本边界与未解问题 <a class="header-anchor" href="#保留版本边界与未解问题" aria-label="Permalink to &quot;保留版本边界与未解问题&quot;">​</a></h2><p>经典实现中的结论必须留在经典版本内。当前主分支已经改变结构，不能把旧函数探针写成对当前产品的完整评测；选定文档页面的“最新”地址也不能抹掉实际版本差别。发言者约束描述的是部分编排路径，本篇没有把它当成普遍授权保证。</p><p>对简单、确定性且内置完整领域检查的应用，终止条件可以有意绑定验收；此时仍需检查这个绑定实际执行了什么，而不是再机械增加一个角色。对开放任务，什么证据足以验收、谁能对缺项负责，仍需要业务决定。下一步应在实际部署中追踪一次预算停止和一次正常终止，核对交付版本、真实测试及上层状态映射，再判断验收责任是否确实独立存在。</p>',27))])}const f=n(h,[["render",l]]);export{_ as __pageData,f as default};
